questionvariables.text:
/* Fonction utilitaire CORRECTE pour Maxima */
ri(a,b) := a + rand(b - a + 1) - 1;

/* Génération des paramètres */
p_a_num: ri(4, 8);
p_a: p_a_num / 10;
p_b: 1 - p_a;
p_a_pct: p_a_num * 10;

pd_a_num: ri(2, 8);
pd_a: pd_a_num / 100;

pd_b_num: ri(1, 5);
pd_b: pd_b_num / 100;

/* Calculs intermédiaires */
p_a_d: p_a * pd_a;
p_b_d: p_b * pd_b;
p_d: p_a_d + p_b_d;

/* Réponse attendue */
ans_correct: p_a_d / p_d;

/* Erreurs classiques */
/* Erreur 1 : A calculé l'intersection P(A inter D) au lieu de la conditionnelle */
err_inter: p_a_d;
/* Erreur 2 : A inversé le conditionnement (a calculé P_A(D) au lieu de P_D(A)) */
err_reverse: pd_a;
/* Erreur 3 : A donné la probabilité marginale P(A) (ignoré la condition) */
err_marg: p_a;
/* Erreur 4 : A calculé la probabilité que ça vienne de B sachant D (l'événement complémentaire) */
err_complement: p_b_d / p_d;
